package com.bank.slot;

import java.util.logging.Logger;

public class PromoSlotOptimizer {

    private static final Logger log = Logger.getLogger(PromoSlotOptimizer.class.getName());

    // Max value choosing non-adjacent slots
    public int maxValue(int[] slotValues) {
        int prev2 = 0, prev1 = 0;                      // best up to i-2, i-1
        for (int v : slotValues) {
            int cur = Math.max(prev1, v + prev2);      // skip vs rob
            prev2 = prev1; prev1 = cur;
        }
        final int best = prev1;
        log.info(() -> "Max non-adjacent promo value = " + best);
        return prev1;
    }
}
