package com.bank.slot;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class HouseRobberDemo {

    private static final Logger log = Logger.getLogger(HouseRobberDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Promo Slot Optimizer (House Robber)");
        int[] slots = {2, 7, 9, 3, 1}; // values in lakhs
        PromoSlotOptimizer opt = new PromoSlotOptimizer();
        log.info("Best = " + opt.maxValue(slots)); // 12 (slots 2+9+1)
    }
}
